insert into public.brands (name, slug, description, banner_url, is_featured, sort_order, is_sample) values ('Kaari Studio', 'kaari-studio', 'Handloom weaves, hand embroidery and handmade jewellery from artisan clusters across India. Kaari means craft.', 'https://images.unsplash.com/photo-1761369332487-777e59fa4bcf?ar=16:9&fit=crop&w=1200&q=80&auto=format', true, 3, true);
insert into public.brands (name, slug, description, banner_url, is_featured, sort_order, is_sample) values ('Sable Row', 'sable-row', 'Tailoring and shirting with a quiet, exact fit. Natural fibres, considered details, nothing extra.', 'https://images.unsplash.com/photo-1619603364904-c0498317e145?ar=16:9&fit=crop&w=1200&q=80&auto=format', true, 4, true);
insert into public.brands (name, slug, description, banner_url, is_featured, sort_order, is_sample) values ('Field & Fold', 'field-and-fold', 'Everyday essentials in organic cotton and denim, designed to be worn hard and washed often.', 'https://images.unsplash.com/photo-1489987707025-afc232f7ea0f?ar=16:9&fit=crop&w=1200&q=80&auto=format', false, 5, true);
