insert into public.brands (name, slug, description, banner_url, is_featured, sort_order, is_sample) values ('Glitch Garden', 'glitch-garden', 'Y2K-born going-out pieces: corsets, crop tops, minis and statement jackets, made in small drops that don''t come back.', 'https://images.unsplash.com/photo-1790283727726-f8ba027df653?ar=16:9&fit=crop&crop=faces&w=1200&q=80&auto=format', true, 7, true);
