insert into public.products (title, slug, brand_id, category_id, size_guide_id, description, fabric, fit, care, tags, status, published_at, is_featured, price, compare_at_price, is_returnable, is_sample) values ('Bias-Cut Satin Slip Dress', 'bias-cut-satin-slip-dress', (select id from public.brands where slug = 'atelier-mira'), (select id from public.categories where slug = 'women-dresses'), null, 'A slip dress cut on the bias so it falls in a clean line from adjustable straps to a mid-calf hem. Wear it alone in the evening or under a knit by day.', '100% viscose satin with a soft sheen.', 'Cut on the bias to skim the body. True to size, or size down for a closer fit.', 'Dry clean recommended. Cool iron on the reverse.', array['occasion', 'evening', 'satin']::text[], 'active', now() - interval '0 days' - interval '0 hours', true, 649000, null, true, true);
